291	function buildExecutionStageWakeup(input: {
292	  issueId: string;
293	  previousState: ParsedExecutionState | null;
294	  nextState: ParsedExecutionState | null;
295	  interruptedRunId: string | null;
296	  requestedByActorType: "user" | "agent";
297	  requestedByActorId: string;
298	}) {
299	  const { issueId, previousState, nextState, interruptedRunId } = input;
300	  if (!nextState) return null;
301	
302	  if (nextState.status === "pending") {
303	    const agentId =
304	      nextState.currentParticipant?.type === "agent" ? (nextState.currentParticipant.agentId ?? null) : null;
305	    const stageChanged =
306	      previousState?.status !== "pending" ||
307	      previousState?.currentStageId !== nextState.currentStageId ||
308	      !executionPrincipalsEqual(previousState?.currentParticipant ?? null, nextState.currentParticipant ?? null);
309	    if (!agentId || !stageChanged) return null;
310	
311	    const reason =
312	      nextState.currentStageType === "approval" ? "execution_approval_requested" : "execution_review_requested";
313	    const executionStage = buildExecutionStageWakeContext({
314	      state: nextState,
315	      wakeRole: nextState.currentStageType === "approval" ? "approver" : "reviewer",
316	      allowedActions: ["approve", "request_changes"],
317	    });
318	
319	    return {
320	      agentId,
321	      wakeup: {
322	        source: "assignment" as const,
323	        triggerDetail: "system" as const,
324	        reason,
325	        payload: {
326	          issueId,
327	          mutation: "update",
328	          executionStage,
329	          ...(interruptedRunId ? { interruptedRunId } : {}),
330	        },
331	        requestedByActorType: input.requestedByActorType,
332	        requestedByActorId: input.requestedByActorId,
333	        contextSnapshot: {
334	          issueId,
335	          taskId: issueId,
336	          wakeReason: reason,
337	          source: "issue.execution_stage",
338	          executionStage,
339	          ...(interruptedRunId ? { interruptedRunId } : {}),
340	        },
341	      },
342	    };
343	  }
344	
345	  if (nextState.status === "changes_requested") {
346	    const agentId = nextState.returnAssignee?.type === "agent" ? (nextState.returnAssignee.agentId ?? null) : null;
347	    const becameChangesRequested =
348	      previousState?.status !== "changes_requested" ||
349	      previousState?.lastDecisionId !== nextState.lastDecisionId ||
350	      !executionPrincipalsEqual(previousState?.returnAssignee ?? null, nextState.returnAssignee ?? null);
351	    if (!agentId || !becameChangesRequested) return null;
352	
353	    const executionStage = buildExecutionStageWakeContext({
354	      state: nextState,
355	      wakeRole: "executor",
356	      allowedActions: ["address_changes", "resubmit"],
357	    });
358	
359	    return {
360	      agentId,
361	      wakeup: {
362	        source: "assignment" as const,
363	        triggerDetail: "system" as const,
364	        reason: "execution_changes_requested",
365	        payload: {
366	          issueId,
